import { getCompatContextProvider } from 'react-querybuilder';
import { X, Copy, Lock, Unlock, ChevronDown, ChevronUp, Plus } from 'lucide-react';
import { ShadcnActionElement } from './shadcn-action-element';
import { ShadcnDragHandle } from './shadcn-drag-handle';
import { ShadcnNotToggle } from './shadcn-not-toggle';
import { ShadcnValueEditor } from './shadcn-value-editor';
import { ShadcnValueSelector } from './shadcn-value-selector';

// Classnames for shadcn/ui styling
export const shadcnControlClassnames = {
  ruleGroup: 'rounded-lg border bg-background p-4 shadow-sm',
  header: 'flex items-center gap-2 mb-2',
  body: 'space-y-2',
  combinators: 'px-2',
  addRule: '',
  addGroup: '',
  removeGroup: '',
  notToggle: '',
  rule: 'flex items-center gap-2 rounded-md border bg-muted/50 p-2',
  fields: '',
  operators: '',
  value: '',
  removeRule: 'ml-auto',
  dragHandle: 'cursor-grab',
  lockRule: '',
  lockGroup: '',
};

// Control elements using shadcn/ui components
export const shadcnControlElements = {
  actionElement: ShadcnActionElement,
  dragHandle: ShadcnDragHandle,
  notToggle: ShadcnNotToggle,
  valueEditor: ShadcnValueEditor,
  valueSelector: ShadcnValueSelector,
  fieldSelector: ShadcnValueSelector,
  combinatorSelector: ShadcnValueSelector,
  operatorSelector: ShadcnValueSelector,
};

// Translations with icons
export const shadcnTranslations = {
  removeRule: { label: <X className="h-4 w-4" />, title: 'Remove rule' },
  removeGroup: { label: <X className="h-4 w-4" />, title: 'Remove group' },
  addRule: {
    label: (
      <>
        <Plus className="mr-1 h-4 w-4" /> Rule
      </>
    ),
    title: 'Add rule',
  },
  addGroup: {
    label: (
      <>
        <Plus className="mr-1 h-4 w-4" /> Group
      </>
    ),
    title: 'Add group',
  },
  cloneRule: { label: <Copy className="h-4 w-4" />, title: 'Clone rule' },
  cloneRuleGroup: { label: <Copy className="h-4 w-4" />, title: 'Clone group' },
  lockRule: { label: <Unlock className="h-4 w-4" />, title: 'Lock rule' },
  lockGroup: { label: <Unlock className="h-4 w-4" />, title: 'Lock group' },
  lockRuleDisabled: { label: <Lock className="h-4 w-4" />, title: 'Unlock rule' },
  lockGroupDisabled: { label: <Lock className="h-4 w-4" />, title: 'Unlock group' },
  shiftActionUp: { label: <ChevronUp className="h-4 w-4" />, title: 'Move up' },
  shiftActionDown: { label: <ChevronDown className="h-4 w-4" />, title: 'Move down' },
};

// Main context provider with all shadcn/ui settings
export const QueryBuilderShadcn = getCompatContextProvider({
  controlClassnames: shadcnControlClassnames,
  controlElements: shadcnControlElements,
  translations: shadcnTranslations,
});

// Re-export components for individual use
export { ShadcnActionElement } from './shadcn-action-element';
export { ShadcnDragHandle } from './shadcn-drag-handle';
export { ShadcnNotToggle } from './shadcn-not-toggle';
export { ShadcnValueEditor } from './shadcn-value-editor';
export { ShadcnValueSelector } from './shadcn-value-selector';

export { toSelectOptions } from './utils';

// Re-export react-querybuilder for convenience
export { QueryBuilder, formatQuery } from 'react-querybuilder';
export type {
  Field,
  RuleGroupType,
  RuleType,
  OptionList,
  ValueEditorProps,
  ActionWithRulesProps,
} from 'react-querybuilder';

import type { ActionWithRulesProps } from 'react-querybuilder';
import { Button } from '../../ui/actions/button';

export type ShadcnActionProps = ActionWithRulesProps & React.ComponentProps<typeof Button>;

export function ShadcnActionElement({
  className,
  handleOnClick,
  label,
  title,
  disabled,
  disabledTranslation,
  // Extract and ignore query-builder specific props
  testID: _testID,
  rules: _rules,
  level: _level,
  path: _path,
  context: _context,
  validation: _validation,
  ruleOrGroup: _ruleOrGroup,
  schema: _schema,
  ...extraProps
}: ShadcnActionProps) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      className={className}
      title={disabledTranslation && disabled ? disabledTranslation.title : title}
      onClick={(e) => handleOnClick(e)}
      disabled={disabled}
      {...extraProps}
    >
      {disabledTranslation && disabled ? disabledTranslation.label : label}
    </Button>
  );
}

ShadcnActionElement.displayName = 'ShadcnActionElement';

import { forwardRef } from 'react';
import type { DragHandleProps } from 'react-querybuilder';
import { GripVertical } from 'lucide-react';

export type ShadcnDragHandleProps = DragHandleProps & React.HTMLAttributes<HTMLSpanElement>;

export const ShadcnDragHandle = forwardRef<HTMLSpanElement, ShadcnDragHandleProps>(
  ({ className, title, ...props }, ref) => (
    <span ref={ref} className={className} title={title} {...props}>
      <GripVertical className="h-5 w-5 cursor-grab text-muted-foreground" />
    </span>
  )
);

ShadcnDragHandle.displayName = 'ShadcnDragHandle';

import type { NotToggleProps } from 'react-querybuilder';
import { Switch } from '../../ui/forms/switch';
import { Label } from '../../ui/display/label';

export type ShadcnNotToggleProps = NotToggleProps;

export function ShadcnNotToggle({
  className,
  handleOnChange,
  label,
  checked,
  title,
  disabled,
  // Extract and ignore query-builder specific props
  testID: _testID,
  level: _level,
  path: _path,
  context: _context,
  validation: _validation,
  schema: _schema,
  ...extraProps
}: ShadcnNotToggleProps) {
  return (
    <div className={`flex items-center gap-2 ${className ?? ''}`} {...extraProps}>
      <Switch
        id="not-toggle"
        checked={checked}
        onCheckedChange={(checked) => handleOnChange(checked)}
        disabled={disabled}
        title={title}
      />
      <Label htmlFor="not-toggle" className="cursor-pointer">
        {label}
      </Label>
    </div>
  );
}

ShadcnNotToggle.displayName = 'ShadcnNotToggle';

import type { ValueEditorProps } from 'react-querybuilder';
import { Input } from '../../ui/forms/input';
import { Textarea } from '../../ui/forms/textarea';
import { Checkbox } from '../../ui/forms/checkbox';
import { Switch } from '../../ui/forms/switch';
import { RadioGroup, RadioGroupItem } from '../../ui/forms/radio-group';
import { Label } from '../../ui/display/label';
import { ShadcnValueSelector } from './shadcn-value-selector';

export type ShadcnValueEditorProps = ValueEditorProps & {
  extraProps?: Record<string, unknown>;
};

export function ShadcnValueEditor(props: ShadcnValueEditorProps) {
  const {
    fieldData,
    operator,
    value,
    handleOnChange,
    title,
    className,
    type,
    inputType,
    values = [],
    disabled,
    path,
    level,
    schema,
    extraProps = {},
  } = props;

  // Handle null/notNull operators
  if (operator === 'null' || operator === 'notNull') {
    return null;
  }

  // Handle between/notBetween operators
  if (
    (operator === 'between' || operator === 'notBetween') &&
    (type === 'select' || type === 'text')
  ) {
    const valueArray = Array.isArray(value) ? value : [value, ''];

    const handleBetweenChange = (val: string, idx: number) => {
      const newValue = [...valueArray];
      newValue[idx] = val;
      handleOnChange(newValue.join(','));
    };

    const editors = ['from', 'to'].map((pos, idx) => {
      if (type === 'text') {
        return (
          <Input
            key={pos}
            type={inputType || 'text'}
            className="w-[100px]"
            value={valueArray[idx] ?? ''}
            onChange={(e) => handleBetweenChange(e.target.value, idx)}
            disabled={disabled}
            placeholder={pos}
            {...extraProps}
          />
        );
      }
      return (
        <ShadcnValueSelector
          key={pos}
          options={values}
          value={valueArray[idx] ?? ''}
          handleOnChange={(v) => handleBetweenChange(v, idx)}
          disabled={disabled}
          path={path}
          level={level}
          schema={schema}
          {...extraProps}
        />
      );
    });

    return (
      <span className="flex items-center gap-2">
        {editors[0]}
        <span className="text-muted-foreground">and</span>
        {editors[1]}
      </span>
    );
  }

  // Handle different input types
  switch (type) {
    case 'select':
    case 'multiselect':
      return (
        <ShadcnValueSelector
          className={className}
          title={title}
          options={values}
          value={value}
          handleOnChange={handleOnChange}
          disabled={disabled}
          multiple={type === 'multiselect'}
          path={path}
          level={level}
          schema={schema}
          {...extraProps}
        />
      );

    case 'textarea':
      return (
        <Textarea
          className={className}
          value={value}
          onChange={(e) => handleOnChange(e.target.value)}
          disabled={disabled}
          title={title}
          placeholder={fieldData?.placeholder}
          {...extraProps}
        />
      );

    case 'switch':
      return (
        <Switch
          className={className}
          checked={!!value}
          onCheckedChange={handleOnChange}
          disabled={disabled}
          title={title}
          {...extraProps}
        />
      );

    case 'checkbox':
      return (
        <Checkbox
          className={className}
          checked={!!value}
          onCheckedChange={handleOnChange}
          disabled={disabled}
          title={title}
          {...extraProps}
        />
      );

    case 'radio':
      return (
        <RadioGroup
          className={className}
          value={value}
          onValueChange={handleOnChange}
          disabled={disabled}
        >
          {values.map((opt) => (
            <div key={opt.name} className="flex items-center space-x-2">
              <RadioGroupItem value={opt.name ?? ''} id={opt.name} disabled={opt.disabled} />
              <Label htmlFor={opt.name}>{opt.label}</Label>
            </div>
          ))}
        </RadioGroup>
      );

    default:
      return (
        <Input
          type={inputType || 'text'}
          className={`w-[180px] ${className ?? ''}`}
          value={value}
          onChange={(e) => handleOnChange(e.target.value)}
          disabled={disabled}
          title={title}
          placeholder={fieldData?.placeholder}
          {...extraProps}
        />
      );
  }
}

ShadcnValueEditor.displayName = 'ShadcnValueEditor';

import type { VersatileSelectorProps } from 'react-querybuilder';
import {
  Select,
  SelectContent,
  SelectTrigger,
  SelectValue,
  SelectGroup,
} from '../../ui/forms/select';

import { toSelectOptions } from './utils';
import {
  MultiSelect,
  type MultiSelectGroup,
  type MultiSelectOption,
} from '../../patterns/multi-select';

export type ShadcnValueSelectorProps = VersatileSelectorProps &
  Omit<React.ComponentPropsWithoutRef<typeof Select>, 'multiple'>;

export function ShadcnValueSelector(props: ShadcnValueSelectorProps) {
  const { className, handleOnChange, options, value, title, disabled, multiple } = props;
  // Use MultiSelect for multiple selection mode
  if (multiple) {
    const valueArray = Array.isArray(value) ? value : value ? [value] : [];
    return (
      <MultiSelect
        options={options as MultiSelectOption[] | MultiSelectGroup[]}
        value={valueArray}
        onChange={(newValue) => handleOnChange(newValue.join(','))}
        disabled={disabled}
        placeholder="Select..."
      />
    );
  }

  return (
    <Select
      items={options as { value: string; label: string }[]}
      value={value as string}
      onValueChange={handleOnChange}
      disabled={disabled}
    >
      <SelectTrigger className={`w-[180px] ${className ?? ''}`} title={title}>
        <SelectValue placeholder="Select..." />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>{toSelectOptions(options)}</SelectGroup>
      </SelectContent>
    </Select>
  );
}

ShadcnValueSelector.displayName = 'ShadcnValueSelector';

import type { OptionList } from 'react-querybuilder';
import { isOptionGroupArray } from 'react-querybuilder';
import { SelectGroup, SelectItem, SelectLabel } from '../../ui/forms/select';

export const toSelectOptions = (list: OptionList) => {
  if (isOptionGroupArray(list)) {
    return list.map((group) => (
      <SelectGroup key={group.label}>
        <SelectLabel>{group.label}</SelectLabel>
        {group.options.map((opt) => (
          <SelectItem key={opt.name} value={opt.name ?? ''} disabled={!!opt.disabled}>
            {opt.label}
          </SelectItem>
        ))}
      </SelectGroup>
    ));
  }
  if (Array.isArray(list)) {
    return list.map((opt) => (
      <SelectItem key={opt.name} value={opt.name ?? ''} disabled={!!opt.disabled}>
        {opt.label}
      </SelectItem>
    ));
  }
  return null;
};
